if base < 2 or base > 9:
        raise ValueError("base must be between 2 and 9")
    if x == 0:
        return '0'
    negative = x < 0
    if negative:
        x = -x
    digits = []
    while x > 0:
        digits.append(str(x % base))
        x //= base
    result = ''.join(reversed(digits))
    return ('-' if negative else '') + result
